#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DType {
    Bool,
    Int8,
    Int16,
    Int32,
    Int64,
    UInt8,
    UInt16,
    UInt32,
    UInt64,
    Float32,
    Float64,
    Complex64,
    Complex128,
    Object,
}

impl DType {
    pub fn kind(self) -> char {
        match self {
            DType::Bool => 'b',
            DType::Int8 | DType::Int16 | DType::Int32 | DType::Int64 => 'i',
            DType::UInt8 | DType::UInt16 | DType::UInt32 | DType::UInt64 => 'u',
            DType::Float32 | DType::Float64 => 'f',
            DType::Complex64 | DType::Complex128 => 'c',
            DType::Object => 'O',
        }
    }

    pub fn precedence(self) -> u8 {
        match self {
            DType::Bool => 0,
            DType::Int8 => 1,
            DType::Int16 => 2,
            DType::Int32 => 3,
            DType::Int64 => 4,
            DType::UInt8 => 5,
            DType::UInt16 => 6,
            DType::UInt32 => 7,
            DType::UInt64 => 8,
            DType::Float32 => 9,
            DType::Float64 => 10,
            DType::Complex64 => 11,
            DType::Complex128 => 12,
            DType::Object => 13,
        }
    }
}

/// Task 1:
/// Given a non-empty collection of dtypes, returns a dtype that appears in the
/// collection and has maximum precedence among them.
///
/// Panics if `types` is empty (the problem statement says it is non-empty).
pub fn find_max_precedence_type(types: Vec<DType>) -> DType {
    types
        .into_iter()
        .max_by_key(|t| t.precedence())
        .expect("types must be non-empty")
}

/// Task 2:
/// Given array dtypes and scalar dtypes, returns the common dtype following the rules:
/// - If only arrays provided: max-precedence dtype from arrays
/// - If only scalars provided: max-precedence dtype from scalars
/// - If both provided:
///   - let amax = max from arrays, smax = max from scalars
///   - if amax.kind() == smax.kind(): return amax
///   - else: return smax
///
/// Returns `None` only if both inputs are empty (allowed by signature, but excluded by the prompt).
pub fn find_common_type(array_types: Vec<DType>, scalar_types: Vec<DType>) -> Option<DType> {
    match (array_types.is_empty(), scalar_types.is_empty()) {
        (true, true) => None,
        (false, true) => Some(find_max_precedence_type(array_types)),
        (true, false) => Some(find_max_precedence_type(scalar_types)),
        (false, false) => {
            let amax = find_max_precedence_type(array_types);
            let smax = find_max_precedence_type(scalar_types);
            if amax.kind() == smax.kind() {
                Some(amax)
            } else {
                Some(smax)
            }
        }
    }
}

